from docx import Document
from docx.shared import Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

p='Bao_cao_du_an_InternChinese.docx'; d=Document(p)
def ap(t,st=None):
    x=d.add_paragraph(style=st); r=x.add_run(t); r.font.name='Times New Roman'; r._element.rPr.rFonts.set(qn('w:eastAsia'),'Times New Roman'); r.font.size=Pt(13); x.paragraph_format.line_spacing=1.5
def tb(head,rows):
    t=d.add_table(rows=1,cols=len(head)); t.style='Table Grid'
    for i,h in enumerate(head): t.cell(0,i).text=h
    for row in rows:
        c=t.add_row().cells
        for i,v in enumerate(row): c[i].text=str(v)
    for row in t.rows:
        for c in row.cells:
            for x in c.paragraphs[0].runs: x.font.name='Times New Roman'; x.font.size=Pt(11)
def box(t):
    x=d.add_table(rows=1,cols=1); c=x.cell(0,0); c.height=Pt(140); c.text=''
    sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'F2F2F2'); c._tc.get_or_add_tcPr().append(sh)
    q=c.paragraphs[0]; q.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=q.add_run('[ ĐẶT ẢNH / SƠ ĐỒ TẠI ĐÂY ]\\n'+t); r.font.name='Times New Roman'; r.font.size=Pt(12); r.italic=True
    z=d.add_paragraph('Hình minh họa: '+t); z.alignment=WD_ALIGN_PARAGRAPH.CENTER
def pg(title,body,head,rows,im):
    d.add_page_break(); ap(title,'Heading 1')
    for x in body: ap(x)
    tb(head,rows); box(im)
pages=[
('PHỤ LỤC C – USER JOURNEY MAP',['Hành trình người dùng gồm khám phá, chuẩn bị, thực hành, đánh giá và ôn tập. Mỗi giai đoạn có mục tiêu, cảm xúc và cơ hội thiết kế riêng.','Trước khi luyện, người dùng cần một điểm bắt đầu rõ ràng. Trong khi luyện, họ cần hỗ trợ vừa đủ. Sau khi luyện, họ cần biết bước tiếp theo thay vì kết thúc đột ngột.'],['Giai đoạn','Hành động','Cơ hội'],[('Khám phá','Xem tình huống','Gợi ý hôm nay'),('Chuẩn bị','Đọc mục tiêu','Vai trò và câu mẫu'),('Thực hành','Gửi câu','Pinyin, dịch, nghe'),('Đánh giá','Xem điểm','Giải thích điểm'),('Ôn tập','Luyện lại','Flashcard')],'Sơ đồ user journey'),
('PHỤ LỤC D – KIẾN TRÚC THÔNG TIN',['Điều hướng chính gồm Tình huống, Từ vựng, Dịch, Lịch sử, Đã lưu và Hồ sơ. Các chức năng quản trị chỉ xuất hiện với tài khoản phù hợp.','Tên tiếng Trung đặt cạnh tiếng Việt để duy trì ngữ cảnh học. Hành động chính dùng nút rõ; tác vụ phụ dùng nút ghost để giảm cạnh tranh thị giác.'],['Khu vực','Nội dung','Hành động'],[('Tình huống','Danh mục, độ khó, tìm kiếm','Mở và luyện'),('Từ vựng','HSK, ngành, flashcard','Lật, nghe, đánh dấu'),('Dịch','Trung–Việt, viết tay','Dịch, sao chép'),('Lịch sử','Phiên và điểm','Xem kết quả'),('Hồ sơ','Thông tin và HSK','Cập nhật')],'Sơ đồ cây điều hướng'),
('PHỤ LỤC E – ĐẶC TẢ TRANG CHỦ',['Trang chủ hiển thị lời chào, số buổi hoàn thành, phút luyện, điểm trung bình và số từ đã nhớ. Khu vực tiếp tục luyện giúp phục hồi phiên dở; gợi ý hôm nay tạo điểm bắt đầu nhanh.','Danh sách tình huống hỗ trợ tìm kiếm, lọc độ khó và lọc ngành. Đây là nơi người dùng chuyển từ nhu cầu chung sang một nhiệm vụ cụ thể.'],['Thành phần','Dữ liệu','Hành vi'],[('Hero','Profile và thống kê','Tóm tắt'),('Tiếp tục','Session dở','Mở lại'),('Gợi ý','Scenario theo ngày','Bắt đầu'),('Danh sách','Scenario/category','Lọc, tìm')],'Ảnh trang chủ desktop/mobile'),
('PHỤ LỤC F – ĐẶC TẢ MÀN HÌNH LUYỆN TẬP',['Màn hình gồm vùng thông tin tình huống và vùng chat. Vùng thông tin giữ bối cảnh, vai trò AI, mục tiêu và câu gợi ý; vùng chat giữ tin nhắn, bản dịch, âm thanh, tiến trình và nút kết thúc.','Mỗi phiên được lưu theo thời gian thực. Khi quay lại, hệ thống tìm phiên in_progress gần nhất và khôi phục nội dung.'],['Trạng thái','Ý nghĩa','Xử lý'],[('Loading','Đang tải','Skeleton'),('Active','Đang hội thoại','Cho gửi tin'),('Busy','Đang gọi AI','Khóa gửi trùng'),('Completed','Hoàn thành','Tạo đánh giá'),('Abandoned','Bỏ cuộc','Lưu lịch sử')],'Ảnh màn hình hội thoại'),
('PHỤ LỤC G – HỆ THỐNG ĐÁNH GIÁ',['Gemini được yêu cầu trả về điểm tổng, năm điểm thành phần, điểm mạnh, điểm yếu, sửa lỗi, đề xuất và tóm tắt. Khi AI lỗi, bộ đánh giá nội bộ dùng số lượt nói, độ dài câu, ký tự Hán, từ lịch sự và câu gợi ý.','Màn hình kết quả trình bày điểm tổng, radar, thanh điểm, ưu/nhược điểm, đề xuất, sửa lỗi và transcript.'],['Chỉ số','Ý nghĩa'],[('Phát âm','Khả năng thể hiện âm thanh'),('Ngữ pháp','Cấu trúc câu'),('Từ vựng','Đa dạng và phù hợp'),('Trôi chảy','Số lượt và liền mạch'),('Giao tiếp','Lịch sự, đúng tình huống')],'Ảnh radar và điểm chi tiết'),
('PHỤ LỤC H – KHO TỪ VỰNG',['Kho gồm HSK 1–9 và từ chuyên ngành. Mỗi từ có chữ Hán, pinyin, nghĩa tiếng Việt, ví dụ và cấp độ. Người dùng có thể xem thẻ hoặc danh sách.','Tìm kiếm hỗ trợ chữ Hán, pinyin, nghĩa và không dấu. Trạng thái learning, remembered, mastered được dùng để tính tiến độ.'],['Tính năng','Giá trị'],[('Lật thẻ','Tự kiểm tra'),('Nghe','Kết nối chữ và âm'),('Đánh dấu','Theo dõi mức nhớ'),('Ôn tập','Củng cố theo phiên')],'Ảnh flashcard'),
('PHỤ LỤC I – CÔNG CỤ DỊCH',['Công cụ hỗ trợ Trung–Việt và Việt–Trung. Khi dịch tiếng Trung, hệ thống tách câu theo kho từ để hiển thị pinyin và nghĩa từng từ.','Người dùng có thể nhập chữ Hán hoặc dùng bảng viết tay. Kết quả có nghe, sao chép, cách nói khác, ghi chú và lịch sử dịch cục bộ.'],['Thành phần','Mô tả'],[('Input','Văn bản hoặc viết tay'),('AI','Dịch theo ngữ cảnh công sở'),('Pinyin','Cách đọc'),('Breakdown','Nghĩa từng từ'),('History','Mục gần đây')],'Ảnh công cụ dịch'),
('PHỤ LỤC J – MÔ HÌNH DỮ LIỆU',['Profiles lưu thông tin người dùng; categories lưu nhóm ngành; scenarios lưu kịch bản; vocabulary lưu từ. Session đại diện một lần luyện, message lưu từng lượt và evaluation lưu kết quả.','User_vocabulary lưu tiến độ; bookmarks liên kết người dùng với tình huống hoặc từ vựng. Cách tách thực thể giúp thống kê và mở rộng thuận lợi.'],['Bảng','Vai trò','Liên kết'],[('profiles','Người dùng','auth'),('scenarios','Tình huống','category'),('sessions','Phiên','profile, scenario'),('messages','Tin nhắn','session'),('evaluations','Điểm','session'),('vocabulary','Từ','category')],'Sơ đồ ERD'),
('PHỤ LỤC K – USER FLOW',['Luồng chính bắt đầu từ đăng nhập. Nếu chưa có session, người dùng vào login; sau xác thực, Private route hiển thị Layout.','Luồng luyện có các nhánh scenario lỗi, session cũ, AI thành công, AI lỗi, mạng lỗi, microphone bị từ chối và người dùng bỏ cuộc. Mỗi nhánh cần phản hồi rõ.'],['Bước','Màn hình','Kết quả'],[('1','Login','Session'),('2','Home','Chọn scenario'),('3','Practice','Gửi message'),('4','Result','Đánh giá'),('5','History/Profile','Theo dõi')],'Sơ đồ user flow'),
('PHỤ LỤC L – HỆ THỐNG GIAO DIỆN',['Giao diện dùng nền sáng, card, dấu ấn chữ Hán; đỏ cho thương hiệu, xanh cho thông tin, vàng cho hành động nổi bật. Chữ Trung và tiếng Việt được phân cấp để người học đọc nhanh.','Responsive có ba điểm chính: mobile, tablet, desktop. Trên mobile, layout chuyển thành thanh trên, nội dung dọc và tab bar dưới.'],['Nguyên tắc','Biểu hiện'],[('Phân cấp','Tiêu đề và hành động rõ'),('Nhất quán','Button, chip, card dùng lại'),('Phản hồi','Loading, error, empty'),('Responsive','Ba breakpoint'),('Học tập','Song ngữ kiểm soát')],'Bảng màu và responsive'),
('PHỤ LỤC M – KIỂM THỬ CHI TIẾT',['Người tham gia tự thực hiện nhiệm vụ; người quan sát chỉ ghi thời gian, lỗi, điểm dừng và câu hỏi. Mỗi nhiệm vụ cần tiền điều kiện, kết quả mong đợi và tiêu chí đạt.','Khi ghi lỗi, cần thêm thiết bị, trình duyệt, bước tái hiện và mức độ nghiêm trọng.'],['Mã','Nhiệm vụ','Kết quả','Mức độ'],[('TC01','Đăng nhập','Vào trang chủ','Cao'),('TC02','Tìm scenario','Mở đúng','Cao'),('TC03','Gửi câu','Có phản hồi','Cao'),('TC04','Hoàn thành','Có Result','Cao'),('TC05','Đánh dấu từ','Cập nhật','TB'),('TC06','Viết tay','Chèn chữ','TB')],'Ảnh buổi kiểm thử'),
('PHỤ LỤC N – BẢNG GHI NHẬN LỖI',['Một lỗi giao diện có thể sửa nhanh, nhưng vấn đề nội dung như câu gợi ý quá khó cần xem lại từ góc độ sư phạm. Các lỗi chặn nhiệm vụ phải xử lý trước.'],['ID','Mô tả','Nguyên nhân','Xử lý'],[('BUG01','Không biết tiếp tục','CTA mờ','Đổi vị trí'),('BUG02','Không hiểu điểm','Thiếu giải thích','Thêm mô tả'),('BUG03','Phụ thuộc dịch','Dịch mặc định','Bật/tắt'),('BUG04','Mất phiên','Chưa khôi phục','Load session'),('BUG05','Tìm có dấu khó','Tìm kiếm hẹp','Chuẩn hóa')],'Ảnh bảng issue'),
('PHỤ LỤC O – KHẢ NĂNG TIẾP CẬN',['Nút cần có nhãn rõ, màu không là tín hiệu duy nhất, nội dung đủ tương phản và ô nhập có placeholder/trạng thái lỗi.','Voice input cần thông báo quyền microphone, trạng thái đang nghe và lỗi nhận diện. Các kiểm tra tiếp theo gồm bàn phím, vùng chạm, tương phản và screen reader.'],['Hạng mục','Cách kiểm tra'],[('Bàn phím','Tab qua nút/input'),('Màu','Kiểm tra tương phản'),('Âm thanh','Có nút phát lại'),('Lỗi','Thông báo dễ hiểu'),('Responsive','Nhiều kích thước')],'Ảnh kiểm tra responsive'),
('PHỤ LỤC P – ROADMAP',['Giai đoạn 1 hoàn thiện prototype và dữ liệu. Giai đoạn 2 kiểm thử với nhiều trình độ. Giai đoạn 3 xây dựng dashboard giảng viên. Giai đoạn 4 tối ưu AI, bảo mật và quota. Giai đoạn 5 mở rộng mobile, nhắc ôn và gamification.'],['Giai đoạn','Mục tiêu','Kết quả'],[('1','Prototype','Bản chạy được'),('2','Kiểm thử','Insight'),('3','Lớp học','Dashboard'),('4','Ổn định','Bảo mật'),('5','Mở rộng','Mobile')],'Roadmap dự án'),
('PHỤ LỤC Q – RỦI RO',['Rủi ro lớn nhất là AI không ổn định, nhận diện giọng nói sai hoặc hết quota. Fallback nội bộ giúp prototype vẫn hoạt động nhưng cần thông báo trung thực rằng điểm là tự động.','Rủi ro dữ liệu gồm lộ tài khoản, lưu âm thanh không cần thiết và sai quyền truy cập. Môi trường thật cần Row Level Security, tối thiểu hóa dữ liệu và giữ API key ở server.'],['Rủi ro','Tác động','Giảm thiểu'],[('AI lỗi','Gián đoạn','Fallback, retry'),('Quota','Không chấm','Giới hạn, cache'),('Micro','Không voice','Cho text'),('Dữ liệu','Mất niềm tin','RLS'),('Nội dung','Học sai','Kiểm duyệt')],'Ma trận rủi ro'),
('PHỤ LỤC R – CHỈ SỐ ĐÁNH GIÁ SẢN PHẨM',['Sản phẩm cần được đánh giá bằng cả chỉ số sử dụng và kết quả học tập. Số lượt truy cập chưa chứng minh người học tiến bộ; cần xem tỷ lệ hoàn thành, điểm trước/sau, số ngày quay lại và mức hài lòng.','Các chỉ số nên được theo dõi theo cấp độ và ngành để tránh so sánh không công bằng giữa người mới bắt đầu và người đã có nền tảng.'],['Chỉ số','Cách đo'],[('Hoàn thành','Phiên hoàn thành / bắt đầu'),('Cải thiện','Điểm trước/sau'),('Duy trì','Số ngày quay lại'),('Từ vựng','Trạng thái nhớ'),('Hài lòng','Khảo sát sau phiên')],'Dashboard chỉ số'),
('PHỤ LỤC S – CAM KẾT CẢI TIẾN',['InternChinese đã chuyển insight “cần được thử nói an toàn trong đúng bối cảnh” thành prototype có thể trình diễn. Tình huống giải quyết thiếu bối cảnh; câu gợi ý giải quyết bí ý tưởng; AI giải quyết thiếu người luyện; điểm số giải quyết thiếu phản hồi; lịch sử giải quyết nhu cầu theo dõi.','Nhóm cam kết tiếp tục kiểm thử với người dùng thật, hoàn thiện nội dung theo ngành và kiểm soát chất lượng AI. Thành công cuối cùng là người học tự tin hơn khi thực hiện giao tiếp thật.'],['Cam kết','Việc cần làm'],[('Nội dung','Kiểm duyệt tình huống'),('AI','Đánh giá prompt/fallback'),('UX','Kiểm thử định kỳ'),('Dữ liệu','Bảo vệ quyền riêng tư'),('Giáo dục','Liên kết lỗi với bài ôn')],'Khu vực ký xác nhận nhóm/giảng viên')
]
for x in pages: pg(*x)
d.save(p); print(p)

